class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options = []  # list to preserve insertion order
        self._votes = {}  # option -> count
        self._voters = {}  # voter -> option

    def add_option(self, option: str) -> None:
        if option not in self._votes:
            self._options.append(option)
            self._votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self._votes:
            raise ValueError(f"Option {option!r} does not exist")
        if voter in self._voters:
            raise ValueError(f"Voter {voter!r} has already voted")
        self._voters[voter] = option
        self._votes[option] += 1

    def winner(self) -> str | None:
        if not self._options:
            return None
        # Iterate in insertion order; later options override ties
        best = None
        best_count = -1
        for option in self._options:
            count = self._votes[option]
            if count >= best_count:
                best = option
                best_count = count
        return best
